-        (void)minimc_proto_send(relay_buf, len);
+        return;
+    }
+    uint8_t err_code = 0x07U;
+    if (!validate_th_relay_resp(frame, &err_code))
+    {
+        char err_kv[32];
+        (void)snprintf(err_kv, sizeof(err_kv), "err_code=0x%02X", (unsigned int)err_code);
+        const mc_dbg_meta_t err_meta = { "ERR", "TH", frame[8], frame[5], "BAD_FRAME" };
+        mc_dbg_emit(&err_meta, err_kv);
+        return;
     }
+    const uint8_t cmd_id = frame[5];
+    const uint8_t seq_u8 = frame[8];
+    const uint32_t elapsed = (uint32_t)(wk_timebase_get() - s_relay_start_ms);
+    s_relay_pending = false;
+
+    char kv[64];
+    const char *st = (cmd_id == MINIMC_CMD_NACK) ? "NACK" : "ACK";
+    if (cmd_id == MINIMC_CMD_NACK)
+    {
+        (void)snprintf(kv, sizeof(kv), "err_code=0x%02X elapsed_ms=%lu", (unsigned int)frame[12], (unsigned long)elapsed);
+    }
+    else
+    {
+        (void)snprintf(kv, sizeof(kv), "elapsed_ms=%lu", (unsigned long)elapsed);
+    }
+    const mc_dbg_meta_t rrx_meta = { "RELAY_RX", "TH", seq_u8, cmd_id, st };
+    mc_dbg_emit(&rrx_meta, kv);
+
+    uint8_t relay_buf[MINIMC_MAX_FRAME_SIZE];
+    relay_frame(frame, len, relay_buf);
+    const bool tx_ok = minimc_proto_send(relay_buf, len);
+    const mc_dbg_meta_t tx_meta = { "TX", "TH", seq_u8, cmd_id, st };
+    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
+}
+
+static void check_th_relay_timeout(uint32_t now_ms)
+{
+    if (!s_relay_pending)
+    {
+        return;
+    }
+    const uint32_t elapsed = (uint32_t)(now_ms - s_relay_start_ms);
+    if (elapsed < MC_RELAY_TIMEOUT_MS)
+    {
+        return;
+    }
+    s_relay_pending = false;
+    char kv[64];
+    (void)snprintf(kv, sizeof(kv), "elapsed_ms=%lu err_code=0x03", (unsigned long)elapsed);
+    const mc_dbg_meta_t rrx_meta = { "RELAY_RX", "TH", s_relay_seq, s_relay_cmd, "TIMEOUT" };
+    const mc_dbg_meta_t err_meta = { "ERR", "TH", s_relay_seq, s_relay_cmd, "TIMEOUT" };
+    mc_dbg_emit(&rrx_meta, kv);
+    mc_dbg_emit(&err_meta, kv);
